#!/usr/bin/env python3
"""Preserve complete actual R33 exact-CI receipts and archive original outputs once."""
import base64, hashlib, json, os, stat
from pathlib import Path
os.umask(0o077)
ROOT=Path("/home/qian/hepta-runtime-optimization-20261106-r33")
PAYLOAD=json.loads(r'''[{"name":"archive_r33_exact_ci.py","bytes":25888,"sha256":"c2d5dcb6db54fedcda728ca658e217578bb852ccb84e4c81bf7a1ac58ca30633","data_base64":""},{"name":"rust-ci-native-01.json","bytes":731,"sha256":"89e2a09b2926d6d866724200297d5db281bff71f5467cc9c81d4e6079ca36ade","data_base64":""},{"name":"rust-ci-native-read-01.json","bytes":5126,"sha256":"1d26855f07f779f0886e4225f6f4b7ca1684832f468b5b819c4d883f363aa45f","data_base64":""}]''')
def need(v,m):
    if not v: raise RuntimeError(m)
def read(path,size,digest):
    need(path.resolve(strict=True)==path,"indirect input")
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    with os.fdopen(fd,"rb") as f:
        a=os.fstat(f.fileno())
        need(stat.S_ISREG(a.st_mode) and a.st_nlink==1 and a.st_size==size,"unsafe input")
        body=f.read(size+1)
        b=os.fstat(f.fileno())
    c=path.lstat()
    fields=("st_dev","st_ino","st_mode","st_uid","st_nlink","st_size","st_mtime_ns","st_ctime_ns")
    need(len(body)==size and hashlib.sha256(body).hexdigest()==digest and all(getattr(a,k)==getattr(b,k)==getattr(c,k) for k in fields),"changed input")
    return body
need(ROOT.resolve(strict=True)==ROOT and ROOT.stat().st_uid==os.geteuid() and os.geteuid()!=0,"fixed operator root")
outputs=[ROOT/x["name"] for x in PAYLOAD]+[ROOT/("exact-ci-evidence-01"+x) for x in [".tar.gz",".manifest.json",".compact.json"]]
need(all(not os.path.lexists(p) for p in outputs),"create-only first CI archive paths required")
read(ROOT/"rust-ci-plan-01.json",541876,"913ba83eeda9f2d2f5e8637008196cfc7b452d111587361f54b7d592582bc203")
read(ROOT/"rust-ci-01/report.json",14133,"8289338ed9a75b31168e59d05fc8c42743cca14c9ce17acaf12f7c567f138516")
decoded=[]
for row in PAYLOAD:
    need(Path(row["name"]).name==row["name"],"unsafe payload name")
    raw=base64.b64decode(row["data_base64"],validate=True)
    need(len(raw)==row["bytes"] and hashlib.sha256(raw).hexdigest()==row["sha256"],"frozen payload mismatch")
    decoded.append((row,raw))
for row,raw in decoded:
    path=ROOT/row["name"]
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW|os.O_CLOEXEC,0o600)
    with os.fdopen(fd,"wb") as f:
        f.write(raw); f.flush(); os.fsync(f.fileno())
    read(path,row["bytes"],row["sha256"])
os.execv("/usr/bin/python3",["/usr/bin/python3","-B",str(ROOT/"archive_r33_exact_ci.py"),"--kind","exact-ci","--plan-sha256","913ba83eeda9f2d2f5e8637008196cfc7b452d111587361f54b7d592582bc203"])
